        // 2. drive c through assertionDisputedCallback as the optimistic asserter
        vm.prank(address(new __InvMutHandleStub()));
        try c.assertionDisputedCallback(assertionId) {
            // call completed
        } catch {
            // reference never reverts here for the asserter
        }
        // 3. general rule: assertionDisputedCallback performs no event logging, so the
        //    PriceRequestAdded(bytes32,uint256,bytes) log topic never appears in c's
        //    deployed bytecode. The mutant's `emit PriceRequestAdded(...)` embeds this
