        bool found = false;
        for (uint256 i = 0; i + 32 <= code.length; i++) {
            bytes32 chunk;
            assembly {
                chunk := mload(add(add(code, 32), i))
            }
            if (chunk == topic) {
                found = true;
                break;
            }
        }
        assertTrue(!found, "disputed callback must not log PriceRequestAdded");
    }
}

